diff --git a/internal/generatedgo/code/base/base.go b/internal/generatedgo/code/base/base.go
index 7709b25..e5576d1 100644
--- a/internal/generatedgo/code/base/base.go
+++ b/internal/generatedgo/code/base/base.go
@@ -11802,6 +11802,7 @@ func (o osFS) Link(a, b string) error                    { return os.Link(o.join
 // files (full per-interpreter filesystem isolation, no disk). Build one with
 // NewMemFS. Safe for concurrent use.
 type MemFS struct {
+	e    *eProbe
 	mu   sync.Mutex
 	root *memNode
 }
@@ -11813,6 +11814,7 @@ func NewMemFS() *MemFS {

 // memNode is a file or directory in a MemFS tree.
 type memNode struct {
+	e        *eBacking
 	parent   *memNode // stable parent identity; retained after unlink
 	name     string
 	dir      bool
@@ -11890,6 +11892,7 @@ func (fsys *MemFS) OpenFile(name string, flag int, perm os.FileMode) (File, erro
 		}
 		node = &memNode{parent: parent, name: base, mode: perm & 0o777, modTime: time.Now()}
 		parent.children[base] = node
+		fsys.eEnroll(node)
 	} else {
 		if flag&os.O_EXCL != 0 && flag&os.O_CREATE != 0 {
 			return nil, &fs.PathError{Op: "open", Path: name, Err: fs.ErrExist}
@@ -12030,9 +12033,11 @@ func (fsys *MemFS) WriteFile(name string, data []byte, perm os.FileMode) error {
 	if err != nil {
 		return &fs.PathError{Op: "writefile", Path: name, Err: err}
 	}
-	cp := make([]byte, len(data))
-	copy(cp, data)
-	parent.children[base] = &memNode{parent: parent, name: base, mode: perm & 0o777, modTime: time.Now(), data: cp}
+	node := &memNode{parent: parent, name: base, mode: perm & 0o777, modTime: time.Now()}
+	fsys.eEnroll(node)
+	node.data = fsys.eResize(node, int64(len(data)))
+	copy(node.data, data)
+	parent.children[base] = node
 	return nil
 }

@@ -12090,7 +12095,7 @@ func (f *memFile) Allocate(end int64) error {
 		return syscall.EISDIR
 	}
 	if end > int64(len(f.node.data)) {
-		f.node.data = resizeMemData(f.node.data, end)
+		f.node.data = f.fsys.eResize(f.node, end)
 		f.node.modTime = time.Now()
 	}
 	return nil
@@ -12147,7 +12152,7 @@ func (f *memFile) ReadAt(p []byte, off int64) (int, error) {
 func (f *memFile) writeAt(p []byte, off int64) int {
 	end := off + int64(len(p))
 	if end > int64(len(f.node.data)) {
-		f.node.data = resizeMemData(f.node.data, end)
+		f.node.data = f.fsys.eResize(f.node, end)
 	}
 	copy(f.node.data[off:], p)
 	f.node.modTime = time.Now()
@@ -12185,7 +12190,7 @@ func (f *memFile) Seek(offset int64, whence int) (int64, error) {
 func (f *memFile) Truncate(size int64) error {
 	f.fsys.mu.Lock()
 	defer f.fsys.mu.Unlock()
-	f.node.data = resizeMemData(f.node.data, size)
+	f.node.data = f.fsys.eResize(f.node, size)
 	f.node.modTime = time.Now()
 	return nil
 }
diff --git a/internal/generatedgo/runtime_instance.go b/internal/generatedgo/runtime_instance.go
