+	s := &Server{eDirect: restore == nil && os.Getenv("MARIAMEM_E_MODE") == "handoff", Guest: p, listener: ln, clients: make(map[net.Conn]*session), slots: make([]bool, p.MaxSessions), queryTimeout: timeout, transfer: transfer, build: build}
 	timing.Mark(ctx, "wire_listener_ready")
