 	timing.Mark(ctx, "guest_timing_read")
@@ -246,14 +247,24 @@ func (s *Server) Snapshot(ctx context.Context, destination string, rollback bool
 		}
 	}()
 	timing.Mark(ctx, "preconditions_destination_ready")
+	if s.eDirect {
+		if err = os.WriteFile(filepath.Join(s.transfer, ".e-request"), nil, 0600); err != nil {
+			s.mu.Unlock()
+			return false, err
+		}
+	}
 	s.stopAccepting()
 	s.mu.Unlock()
 	defer os.RemoveAll(s.transfer)
-	if err = s.finish(ctx, true); err != nil {
